return [{
  json: {
    trustedIpHeader: 'cf-connecting-ip',
    modelName: 'models/gemini-3.6-flash',
    quotaUrl: 'https://code-a-cuisine-edd75-default-rtdb.europe-west1.firebasedatabase.app/privateQuota/v2/state.json',
    recipesUrl: 'https://code-a-cuisine-edd75-default-rtdb.europe-west1.firebasedatabase.app/recipes.json'
  }
}];

/**
 * Parses a strict dotted IPv4 address into octets, or returns null.
 * @param value Value to validate or store.
 */
function ipv4Parts(value) {
  const parts = value.split('.');
  const valid = parts.length === 4 && parts.every(/** Checks whether this item satisfies the validation. @param part Current callback input. */ (part) => /^(0|[1-9]\d{0,2})$/.test(part) && Number(part) <= 255);
  return valid ? parts.map(Number) : null;
}



/**
 * Converts an embedded dotted IPv4 suffix to two IPv6 groups.
 * @param value Value to validate or store.
 */
function expandDottedSuffix(value) {
  if (!value.includes('.')) return value;
  const boundary = value.lastIndexOf(':');
  const parts = ipv4Parts(value.slice(boundary + 1));
  if (boundary < 0 || !parts) return '';
  return value.slice(0, boundary + 1) + ((parts[0] << 8) | parts[1]).toString(16)
    + ':' + ((parts[2] << 8) | parts[3]).toString(16);
}



/**
 * Expands a valid IPv6 address to exactly eight numeric groups.
 * @param value Value to validate or store.
 */
function ipv6Parts(value) {
  const expanded = expandDottedSuffix(value);
  if (!expanded || !/^[\da-f:]+$/i.test(expanded) || expanded.includes(':::')) return null;
  const halves = expanded.split('::');
  if (halves.length > 2) return null;
  const left = halves[0] ? halves[0].split(':') : [];
  const right = halves[1] ? halves[1].split(':') : [];
  if ([...left, ...right].some(/** Checks whether this item meets the condition. @param part Current callback input. */ (part) => !/^[\da-f]{1,4}$/i.test(part))) return null;
  const missing = 8 - left.length - right.length;
  if (halves.length === 1 && missing !== 0 || halves.length === 2 && missing < 1) return null;
  return [...left, ...Array(missing).fill('0'), ...right].map(/** Maps the current item to its output value. @param part Current callback input. */ (part) => parseInt(part, 16));
}



/**
 * Returns one canonical quota identity, merging IPv4-mapped IPv6 with IPv4.
 * @param value Value to validate or store.
 */
function normalizeIp(value) {
  if (typeof value !== 'string' || value.length > 45) return null;
  const candidate = value.trim();
  const v4 = ipv4Parts(candidate);
  if (v4) return v4.join('.');
  const v6 = ipv6Parts(candidate);
  if (!v6) return null;
  if (v6.slice(0, 5).every(/** Checks whether this item satisfies the validation. @param part Current callback input. */ (part) => part === 0) && v6[5] === 65535) {
    return [v6[6] >> 8, v6[6] & 255, v6[7] >> 8, v6[7] & 255].join('.');
  }
  return v6.map(/** Maps the current item to its output value. @param part Current callback input. */ (part) => part.toString(16).padStart(4, '0')).join(':');
}



/**
 * Reads only the single client-IP header overwritten by the configured trusted proxy.
 * @param headers Incoming request headers.
 * @param trustedHeader Single client-IP header overwritten by the trusted proxy.
 */
function clientIp(headers, trustedHeader) {
  if (!['cf-connecting-ip', 'x-real-ip'].includes(trustedHeader)) return null;
  const entry = Object.entries(headers).find(/** Checks whether the current item is the requested match. @param [name] Current callback input. */ ([name]) => name.toLowerCase() === trustedHeader);
  return normalizeIp(entry?.[1]);
}



/**
 * Parses a bounded positive amount in the units accepted by the ingredient form.
 * @param value Value to validate or store.
 */
function parseAmount(value) {
  if (typeof value !== 'string' || value.length > 30) return null;
  const match = value.trim().match(/^(\d+(?:[.,]\d+)?)\s*(g|ml|piece|pieces)?$/i);
  if (!match) return null;
  const amount = Number(match[1].replace(',', '.'));
  const unit = (match[2] || '').toLowerCase().replace(/^pieces?$/, '');
  return Number.isFinite(amount) && amount > 0 && amount <= 10000 ? { amount, unit } : null;
}



/**
 * Returns whether an ingredient contains a valid name and positive quantity.
 * @param entry Ingredient entry to validate.
 */
function validIngredient(entry) {
  if (typeof entry?.ingredient !== 'string') return false;
  const name = entry.ingredient.trim();
  return name.length > 0 && name.length <= 80 && /[\p{L}]/u.test(name)
    && /^[\p{L}\p{N} .,'’()\-/]+$/u.test(name) && !!parseAmount(entry.servingSize);
}



/**
 * Normalizes a food name for exact ingredient coverage and duplicate checks.
 * @param entry Ingredient entry to validate.
 */
function foodName(entry) {
  return String(entry?.ingredient ?? '').trim().toLowerCase();
}



/**
 * Rejects known animal ingredients for vegetarian and vegan requests.
 * @param entry Ingredient entry to validate.
 * @param diet Selected dietary preference.
 */
function violatesDiet(entry, diet) {
  const name = foodName(entry);
  const meat = /\b(chicken|beef|pork|bacon|ham|salami|pastrami|lamb|turkey|duck|fish|salmon|tuna|shrimp|prawn|anchov\w*|gelatin\w*|lard|meat|sausage|huhn|hähnchen|rind\w*|schwein\w*|speck|schinken|fisch|lachs|thunfisch|garnele\w*|wurst)\b/i;
  const dairy = /\b(egg\w*|milk|cream|butter|cheese|yogu?rt|honey|whey|casein|ghee|parmesan|mozzarella|feta|ei|eier|milch|sahne|käse|honig|joghurt|quark)\b/i;
  const plantDairy = /\b(soy|soja|oat|hafer|almond|mandel|coconut|kokos|peanut|erdnuss|cashew|vegan|plant)\w*\b/i;
  if (!['vegetarian', 'vegan'].includes(diet)) return false;
  if (meat.test(name)) return true;
  return diet === 'vegan' && dairy.test(name) && !plantDairy.test(name);
}



/**
 * Validates request choices without coercing arbitrary values to valid input.
 * @param request Validated recipe requirements.
 */
function requestErrors(request) {
  const errors = [];
  if (!Number.isInteger(request.portionsAmount) || request.portionsAmount < 1 || request.portionsAmount > 12) errors.push('Portions must be between 1 and 12.');
  if (!Number.isInteger(request.cooksAmount) || request.cooksAmount < 1 || request.cooksAmount > 3) errors.push('Cooks must be between 1 and 3.');
  if (!['quick', 'medium', 'complex'].includes(request.cookingTime)) errors.push('Invalid cooking time.');
  if (!['german', 'italian', 'japanese', 'indian', 'gourmet', 'fusion'].includes(request.cuisine)) errors.push('Invalid cuisine.');
  if (!['vegetarian', 'vegan', 'keto', 'no preferences'].includes(request.dietPreferences)) errors.push('Invalid diet preference.');
  return [...errors, ...ingredientErrors(request)];
}



/**
 * Checks ingredient bounds, duplicate names and achievable diet-compatible coverage.
 * @param request Validated recipe requirements.
 */
function ingredientErrors(request) {
  const entries = request.ingredients;
  if (!Array.isArray(entries) || entries.length < 1 || entries.length > 30) return ['Please provide between 1 and 30 ingredients.'];
  if (entries.some(/** Checks whether this item meets the condition. @param entry Current callback input. */ (entry) => !validIngredient(entry))) return ['Every ingredient needs a valid name and a positive amount (g, ml or pieces).'];
  if (new Set(entries.map(foodName)).size !== entries.length) return ['Please combine duplicate ingredients.'];
  const compatible = entries.filter(/** Checks whether the current item matches the filter. @param entry Current callback input. */ (entry) => !violatesDiet(entry, request.dietPreferences));
  return compatible.length < Math.ceil(entries.length * 0.7)
    ? ['Your ingredients do not allow 70% coverage with the selected diet. Please adjust ingredients or diet.'] : [];
}



/**
 * Builds a sanitized request context; absent proxy configuration fails closed.
 * @param item Webhook input item.
 * @param config Configuration for this operation.
 * @param now Current time in milliseconds.
 * @param statusOnly Whether only the quota endpoint is being validated.
 */
function validateRequest(item, config, now = Date.now(), statusOnly = false) {
  const request = item.body && typeof item.body === 'object' ? item.body : {};
  const errors = statusOnly ? [] : requestErrors(request);
  const ip = clientIp(item.headers ?? {}, config.trustedIpHeader);
  if (!ip) errors.push('A verified client IP is unavailable. Please contact the site operator.');
  if (!statusOnly && !/^models\/gemini-[\w.-]+$/.test(config.modelName ?? '')) errors.push('The recipe model is not configured. Please contact the site operator.');
  const dayKey = new Date(now).toISOString().slice(0, 10);
  const ipKey = ip?.replaceAll('.', '_').replaceAll(':', '_') ?? '';
  return { request, ipKey, dayKey, valid: errors.length === 0, errors };
}



return [{ json: validateRequest($('Recipe Request').first().json, $input.first().json, Date.now(), false) }];

const RECIPE_COST = 3;
const IP_LIMIT = 3;
const SYSTEM_LIMIT = 12;
const RATE_WINDOW_MS = 10000;

/**
 * Validates a persisted quota counter; corrupted state must never reset silently.
 * @param value Value to validate or store.
 */
function quotaCount(value) {
  if (value === undefined) return 0;
  if (!Number.isSafeInteger(value) || value < 0) throw new Error('Invalid quota state.');
  return value;
}



/**
 * Returns a UTC-day snapshot with all counters expressed in recipes.
 * @param state Persisted quota state.
 * @param context Request identity and quota context.
 */
function quotaStatus(state, context) {
  const day = state?.days?.[context.dayKey];
  const ipUsed = quotaCount(day?.ips?.[context.ipKey]);
  const systemUsed = quotaCount(day?.used);
  return { ipLimit: IP_LIMIT, ipUsed, ipRemaining: Math.max(0, IP_LIMIT - ipUsed),
    systemLimit: SYSTEM_LIMIT, systemUsed, systemRemaining: Math.max(0, SYSTEM_LIMIT - systemUsed) };
}



/**
 * Builds a reservation proposal that can only be committed with the matching Firebase ETag.
 * @param state Persisted quota state.
 * @param context Request identity and quota context.
 * @param now Current time in milliseconds.
 */
function reserveQuota(state, context, now = Date.now()) {
  const quota = quotaStatus(state, context);
  const lastRequest = quotaCount(state?.lastRequests?.[context.ipKey]);
  if (lastRequest && now - lastRequest < RATE_WINDOW_MS) return { allowed: false, quota, detail: 'Too many requests. Please wait 10 seconds.' };
  if (quota.ipRemaining < RECIPE_COST || quota.systemRemaining < RECIPE_COST) {
    return { allowed: false, quota, detail: 'Daily recipe quota exceeded. Each request reserves 3 recipes. Please try again tomorrow (UTC).' };
  }
  const nextState = incrementReservation(state, context, now);
  return { allowed: true, nextState, quota: quotaStatus(nextState, context) };
}



/**
 * Copies all existing state and increments both quotas and the throttle atomically.
 * @param state Persisted quota state.
 * @param context Request identity and quota context.
 * @param now Current time in milliseconds.
 */
function incrementReservation(state, context, now) {
  const next = JSON.parse(JSON.stringify(state ?? { days: {}, lastRequests: {} }));
  next.days ??= {};
  next.lastRequests ??= {};
  const day = next.days[context.dayKey] ?? { used: 0, ips: {} };
  day.ips ??= {};
  day.used = quotaCount(day.used) + RECIPE_COST;
  day.ips[context.ipKey] = quotaCount(day.ips[context.ipKey]) + RECIPE_COST;
  next.days[context.dayKey] = day;
  next.lastRequests[context.ipKey] = now;
  return next;
}



/**
 * Rejects failed, malformed or unversioned Firebase reads before any paid operation.
 * @param response HTTP response to inspect.
 */
function quotaRead(response) {
  if (response.statusCode !== 200 || !response.headers?.etag) throw new Error('Quota storage is unavailable.');
  const state = response.body;
  if (state !== null && (!state || typeof state !== 'object' || Array.isArray(state))) throw new Error('Invalid quota state.');
  if (state !== null && (!state.days || !state.lastRequests)) throw new Error('Incomplete quota state.');
  return state;
}



const context = $('Validate Request').first().json;
const result = $input.first().json;
const state = quotaRead(result);
return [{ json: { ...context, ...reserveQuota(state, context), etag: result.headers.etag } }];

/**
 * Parses a bounded positive amount in the units accepted by the ingredient form.
 * @param value Value to validate or store.
 */
function parseAmount(value) {
  if (typeof value !== 'string' || value.length > 30) return null;
  const match = value.trim().match(/^(\d+(?:[.,]\d+)?)\s*(g|ml|piece|pieces)?$/i);
  if (!match) return null;
  const amount = Number(match[1].replace(',', '.'));
  const unit = (match[2] || '').toLowerCase().replace(/^pieces?$/, '');
  return Number.isFinite(amount) && amount > 0 && amount <= 10000 ? { amount, unit } : null;
}



/**
 * Returns whether an ingredient contains a valid name and positive quantity.
 * @param entry Ingredient entry to validate.
 */
function validIngredient(entry) {
  if (typeof entry?.ingredient !== 'string') return false;
  const name = entry.ingredient.trim();
  return name.length > 0 && name.length <= 80 && /[\p{L}]/u.test(name)
    && /^[\p{L}\p{N} .,'’()\-/]+$/u.test(name) && !!parseAmount(entry.servingSize);
}



/**
 * Normalizes a food name for exact ingredient coverage and duplicate checks.
 * @param entry Ingredient entry to validate.
 */
function foodName(entry) {
  return String(entry?.ingredient ?? '').trim().toLowerCase();
}



/**
 * Rejects known animal ingredients for vegetarian and vegan requests.
 * @param entry Ingredient entry to validate.
 * @param diet Selected dietary preference.
 */
function violatesDiet(entry, diet) {
  const name = foodName(entry);
  const meat = /\b(chicken|beef|pork|bacon|ham|salami|pastrami|lamb|turkey|duck|fish|salmon|tuna|shrimp|prawn|anchov\w*|gelatin\w*|lard|meat|sausage|huhn|hähnchen|rind\w*|schwein\w*|speck|schinken|fisch|lachs|thunfisch|garnele\w*|wurst)\b/i;
  const dairy = /\b(egg\w*|milk|cream|butter|cheese|yogu?rt|honey|whey|casein|ghee|parmesan|mozzarella|feta|ei|eier|milch|sahne|käse|honig|joghurt|quark)\b/i;
  const plantDairy = /\b(soy|soja|oat|hafer|almond|mandel|coconut|kokos|peanut|erdnuss|cashew|vegan|plant)\w*\b/i;
  if (!['vegetarian', 'vegan'].includes(diet)) return false;
  if (meat.test(name)) return true;
  return diet === 'vegan' && dairy.test(name) && !plantDairy.test(name);
}



/**
 * Parses a nonnegative nutrition value with an exact unit.
 * @param value Value to validate or store.
 * @param unit Expected ingredient or nutrition unit.
 */
function nutrient(value, unit) {
  if (typeof value !== 'string') throw new Error('Nutrition must include units.');
  const match = value.trim().match(/^(\d+(?:[.,]\d+)?)\s*(kcal|g|%)$/);
  if (!match || match[2] !== unit) throw new Error('Invalid nutrition amount or unit.');
  const amount = Number(match[1].replace(',', '.'));
  if (!Number.isFinite(amount) || amount > 100000) throw new Error('Invalid nutrition amount.');
  return amount;
}



/**
 * Checks macro energy shares and returns the numeric per-portion nutrition.
 * @param snapshot Nutrition snapshot.
 */
function validateSnapshot(snapshot) {
  if (!snapshot) throw new Error('Nutrition is missing.');
  const calories = nutrient(snapshot.calories, 'kcal');
  const values = ['proteins', 'fats', 'carbs'].map(/** Maps the current item to its output value. @param key Current callback input. */ (key) => nutrient(snapshot[key], 'g'));
  const energy = values.map(/** Maps the current item to its output value. @param value Current callback input. @param index Current callback input. */ (value, index) => value * (index === 1 ? 9 : 4));
  const totalEnergy = energy.reduce(/** Combines the accumulated value with the current item. @param sum Current callback input. @param value Current callback input. */ (sum, value) => sum + value, 0);
  if (calories <= 0 || totalEnergy <= 0 || Math.abs(calories - totalEnergy) > Math.max(10, calories * 0.1)) throw new Error('Nutrition energy is inconsistent.');
  ['proteins', 'fats', 'carbs'].forEach(/** Processes the current item in the enclosing operation. @param key Current callback input. @param index Current callback input. */ (key, index) => {
    const percent = nutrient(snapshot[key + 'Percent'], '%');
    if (percent > 100 || Math.abs(percent - energy[index] / totalEnergy * 100) > 2) throw new Error('Macro percentages are inconsistent.');
  });
  return [calories, ...values];
}



/**
 * Verifies total nutrition scales with portions and enforces the documented keto limit.
 * @param recipe Recipe to process.
 * @param request Validated recipe requirements.
 */
function validateNutrition(recipe, request) {
  const portion = validateSnapshot(recipe.nutritionalInformation?.perPortion);
  const total = validateSnapshot(recipe.nutritionalInformation?.total);
  portion.forEach(/** Processes the current item in the enclosing operation. @param value Current callback input. @param index Current callback input. */ (value, index) => {
    const expected = value * request.portionsAmount;
    if (Math.abs(total[index] - expected) > Math.max(1, expected * 0.02)) throw new Error('Total nutrition does not match portions.');
  });
  if (request.dietPreferences === 'keto' && nutrient(recipe.nutritionalInformation.perPortion.carbsPercent, '%') > 10) {
    throw new Error('Keto recipes must have at most 10% carbohydrate energy.');
  }
}



/**
 * Validates one chronological instruction and its explicit dependencies.
 * @param step Direction to validate.
 * @param index Zero-based item position.
 * @param steps Chronological recipe directions.
 * @param cooks Number of cooks.
 */
function validateStep(step, index, steps, cooks) {
  if (step?.order !== index + 1 || !Number.isInteger(step.cook) || step.cook < 1 || step.cook > cooks) throw new Error('Invalid step order or cook.');
  if (typeof step.title !== 'string' || !step.title.trim() || typeof step.description !== 'string' || !step.description.trim()) throw new Error('Incomplete direction.');
  if (!Number.isFinite(step.startMinute) || step.startMinute < 0 || !Number.isFinite(step.durationMinutes) || step.durationMinutes <= 0) throw new Error('Invalid step timing.');
  if (index && step.startMinute < steps[index - 1].startMinute) throw new Error('Directions are not chronological.');
  if (!Array.isArray(step.dependsOn) || typeof step.parallel !== 'boolean') throw new Error('Missing step dependencies or parallel marker.');
  for (const dependency of step.dependsOn) {
    if (!Number.isInteger(dependency) || dependency < 1 || dependency >= step.order) throw new Error('Invalid step dependency.');
    const previous = steps[dependency - 1];
    if (previous.startMinute + previous.durationMinutes > step.startMinute) throw new Error('Step starts before its dependency finishes.');
  }
}



/**
 * Returns whether two scheduled directions overlap in time.
 * @param first First scheduled direction.
 * @param second Second scheduled direction.
 */
function overlaps(first, second) {
  return first.startMinute < second.startMinute + second.durationMinutes
    && second.startMinute < first.startMinute + first.durationMinutes;
}



/**
 * Checks cook availability and confirms parallel flags correspond to real parallel work.
 * @param steps Chronological recipe directions.
 * @param cooks Number of cooks.
 */
function validateParallel(steps, cooks) {
  for (const step of steps) {
    const concurrent = steps.filter(/** Checks whether the current item matches the filter. @param other Current callback input. */ (other) => other !== step && overlaps(step, other));
    if (concurrent.some(/** Checks whether this item meets the condition. @param other Current callback input. */ (other) => other.cook === step.cook)) throw new Error('One cook has overlapping tasks.');
    if (step.parallel !== (concurrent.length > 0)) throw new Error('Parallel marker does not match the schedule.');
  }
  const assigned = new Set(steps.map(/** Maps the current item to its output value. @param step Current callback input. */ (step) => step.cook));
  if (assigned.size !== cooks || cooks > 1 && !steps.some(/** Checks whether this item meets the condition. @param step Current callback input. */ (step) => step.parallel)) throw new Error('Incomplete cook task allocation.');
}



/**
 * Checks chronological order, task allocation and total cooking duration.
 * @param recipe Recipe to process.
 * @param cooks Number of cooks.
 * @param minutes Maximum cooking duration.
 */
function validateDirections(recipe, cooks, minutes) {
  const steps = recipe.directions;
  if (!Array.isArray(steps) || steps.length < cooks || steps.length > 50) throw new Error('Invalid directions.');
  steps.forEach(/** Processes the current item in the enclosing operation. @param step Current callback input. @param index Current callback input. */ (step, index) => validateStep(step, index, steps, cooks));
  validateParallel(steps, cooks);
  const finish = Math.max(...steps.map(/** Maps the current item to its output value. @param step Current callback input. */ (step) => step.startMinute + step.durationMinutes));
  if (finish > minutes) throw new Error('Directions exceed the cooking time.');
}



/**
 * Checks a recipe title without accepting empty, duplicate or placeholder headings.
 * @param title Input used by this operation.
 */
function validTitle(title) {
  return typeof title === 'string' && title.trim().length >= 5 && title.length <= 120
    && title.trim().split(/\s+/).length >= 2
    && !/\b(test\d*|recipe\s*xyz|lorem|placeholder|untitled)\b/i.test(title);
}



/**
 * Parses an explicit duration in minutes and enforces the selected category.
 * @param value Value to validate or store.
 * @param category Selected cooking-time category.
 */
function cookingMinutes(value, category) {
  const match = typeof value === 'string' && value.match(/^(\d+)\s*(min|minutes)$/i);
  const minutes = match ? Number(match[1]) : NaN;
  const valid = category === 'quick' ? minutes <= 20 : category === 'medium' ? minutes >= 20 && minutes <= 45 : minutes > 45;
  if (!Number.isFinite(minutes) || minutes <= 0 || minutes > 1440 || !valid) throw new Error('Cooking time is outside the selected range.');
  return minutes;
}



/**
 * Derives the final ingredient quantity from the supplied one-portion base.
 * @param entry Ingredient entry to validate.
 * @param portions Requested portion count.
 * @param available Available input ingredient quantity.
 */
function scaleIngredient(entry, portions, available) {
  if (!validIngredient(entry)) throw new Error('Invalid recipe ingredient quantity.');
  const base = parseAmount(entry.perPortionServingSize);
  const total = parseAmount(entry.servingSize);
  if (!base || base.unit !== total.unit) throw new Error('Missing per-portion ingredient quantity.');
  const scaled = Math.round(base.amount * portions * 1000) / 1000;
  if (scaled <= 0 || scaled > 10000 || Math.abs(scaled - total.amount) > 0.001) throw new Error('Ingredient quantity does not scale with portions.');
  if (available && (available.unit !== total.unit || scaled > available.amount + 0.001)) throw new Error('Insufficient ingredient quantities for selected servings.');
  entry.servingSize = `${scaled}${base.unit}`;
}



/**
 * Checks exact ingredient coverage, disjoint extras and positive scaled quantities.
 * @param recipe Recipe to process.
 * @param request Validated recipe requirements.
 */
function validateRecipeIngredients(recipe, request) {
  const own = recipe.ingredients?.yourIngredients;
  const extras = recipe.ingredients?.extraIngredients;
  if (!Array.isArray(own) || !Array.isArray(extras) || extras.length > 3) throw new Error('Invalid ingredient lists.');
  const all = [...own, ...extras];
  if (new Set(all.map(foodName)).size !== all.length) throw new Error('Duplicate recipe ingredients.');
  const supplied = new Map(request.ingredients.map(/** Maps the current item to its output value. @param entry Current callback input. */ (entry) => [foodName(entry), parseAmount(entry.servingSize)]));
  if (own.length < Math.ceil(supplied.size * 0.7) || own.some(/** Checks whether this item meets the condition. @param entry Current callback input. */ (entry) => !supplied.has(foodName(entry)))) throw new Error('Ingredient coverage must be at least 70%.');
  own.forEach(/** Processes the current item in the enclosing operation. @param entry Current callback input. */ (entry) => scaleIngredient(entry, request.portionsAmount, supplied.get(foodName(entry))));
  validateExtras(extras, supplied, request.portionsAmount);
  if (all.some(/** Checks whether this item meets the condition. @param entry Current callback input. */ (entry) => violatesDiet(entry, request.dietPreferences))) throw new Error('Ingredients violate the selected diet.');
}



/**
 * Limits extra ingredients to common pantry basics and excludes supplied foods.
 * @param extras Input used by this operation.
 * @param supplied Input ingredient quantities indexed by name.
 * @param portions Requested portion count.
 */
function validateExtras(extras, supplied, portions) {
  const basics = /^(salt|pepper|black pepper|water|olive oil|oil|butter|flour|sugar|vinegar|garlic|onion|lemon|lemon juice|paprika|cumin|turmeric|curry powder|soy sauce|basil|oregano|parsley|salz|pfeffer|wasser|olivenöl|öl|mehl|zucker|essig|knoblauch|zwiebel|zitrone)$/i;
  for (const entry of extras) {
    if (!basics.test(foodName(entry)) || supplied.has(foodName(entry))) throw new Error('Extra ingredients must be missing pantry basics.');
    scaleIngredient(entry, portions);
  }
}



/**
 * Validates the selected preferences and every structured part of one recipe.
 * @param recipe Recipe to process.
 * @param request Validated recipe requirements.
 */
function validateRecipe(recipe, request) {
  if (recipe.portionsAmount !== request.portionsAmount || recipe.cooksAmount !== request.cooksAmount) throw new Error('Portions or cooks do not match.');
  for (const key of ['cuisine', 'dietPreferences', 'cookingTime']) {
    if (recipe.preferences?.[key] !== request[key]) throw new Error('Recipe preferences do not match.');
  }
  const minutes = cookingMinutes(recipe.cookingTime, request.cookingTime);
  validateRecipeIngredients(recipe, request);
  validateNutrition(recipe, request);
  validateDirections(recipe, request.cooksAmount, minutes);
}



/**
 * Validates all three AI suggestions before returning or persisting any result.
 * @param raw Raw JSON recipe response.
 * @param request Validated recipe requirements.
 */
function validateRecipes(raw, request) {
  const recipes = JSON.parse(String(raw).replace(/^```(?:json)?\s*|\s*```$/gi, '').trim());
  if (!Array.isArray(recipes) || recipes.length !== 3) throw new Error('Exactly three recipes are required.');
  if (recipes.some(/** Checks whether this item meets the condition. @param recipe Current callback input. */ (recipe) => !validTitle(recipe?.title))) throw new Error('Invalid recipe title.');
  if (new Set(recipes.map(/** Maps the current item to its output value. @param recipe Current callback input. */ (recipe) => recipe.title.trim().toLowerCase())).size !== 3) throw new Error('Recipe titles must be unique.');
  recipes.forEach(/** Processes the current item in the enclosing operation. @param recipe Current callback input. */ (recipe) => validateRecipe(recipe, request));
  const methods = recipes.map(/** Maps the current item to its output value. @param recipe Current callback input. */ (recipe) => JSON.stringify(recipe.directions.map(/** Maps the current item to its output value. @param step Current callback input. */ (step) => step.description.trim().toLowerCase())));
  if (new Set(methods).size !== 3) throw new Error('Recipes must differ in preparation, not only in title.');
  return recipes;
}



